{
  "technical_and_design_decisions": [
    "Use Ambari REST API and plugin extension points to add an option for provisioning Spring XD on YARN.",
    "Integrate Spring Cloud Config client into spring-bus modules, replacing local property placeholders with centralized config server sources.",
    "Profile Spring Integration 4.2 channels using VisualVM/JProfiler and apply tuning such as task executor adjustments and batched dispatching.",
    "Create a benchmark harness based on JMH or Spring XD metrics to measure serialization size and latency for typical payloads.",
    "For fsUri=file://, detect the URI scheme and instantiate Hadoop LocalFileSystem instead of DistributedFileSystem, keeping existing hdfs:// behavior unchanged.",
    "Extend the Sqoop job launcher to accept a key-value map of system properties and forward them as -D JVM arguments to the spawned Java process.",
    "Perform spring-bus architecture review and apply minimal refactoring to close foundation gaps without rewriting modules.",
    "Target Java 8 compatibility for the legacy Spring XD/SI components, ignoring the Java 17 requirement of later Spring Framework 6."
  ],
  "assumptions": [
    "Source code for Spring XD, Spring Integration, and spring-bus is available and buildable in the local environment.",
    "A test Ambari cluster or a local sandbox emulation is available for validating YARN deployment and upgrade.",
    "Performance tests are run on representative hardware with typical message volumes.",
    "The spring-bus review yields only minor foundational changes, not a full redesign.",
    "Documentation is maintained in the repository's existing format (Markdown/AsciiDoc) and updated in-place.",
    "The developer has working knowledge of the Spring ecosystem, so no additional training time is included.",
    "Effort covers implementation, testing, and documentation of the increment but excludes post-release production support.",
    "For U7, multi-container split-file behavior is accepted as developer responsibility and only documented, not prevented."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Setup development environment and build tooling",
      "activity_description": "Prepare local workspace, checkout relevant repositories (Spring XD, SI, spring-bus), configure Maven/Gradle, and ensure ability to run existing tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Design U1 Ambari YARN support",
      "activity_description": "Analyze requirements and design the option to support Apache Ambari installed Spring XD on YARN, define plugin API changes, configuration model, and cluster setup flow.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Implement U1 Ambari YARN support",
      "activity_description": "Code the plugin changes to allow establishing cluster via Ambari, including CLI/UI option, REST calls, and YARN application launch.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Test and document U1",
      "activity_description": "Create/adapt integration tests for Ambari-based cluster startup, and write user documentation for the new option.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Implement U2 spring-cloud-config for spring-bus",
      "activity_description": "Integrate Spring Cloud Config client into spring-bus modules, refactor property sources to fetch external properties centrally; include unit tests.",
      "most_likely_effort": 35
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Investigate and remediate SI 4.2 channel performance (U3)",
      "activity_description": "Profile Spring Integration 4.2 channels, identify bottlenecks, implement corrective code changes (e.g., executor tuning, batching) and verify improvements.",
      "most_likely_effort": 50
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Baseline serialization measurement in XD (U4)",
      "activity_description": "Build a benchmarking harness to measure serialization characteristics (size, time) for XD message payloads, execute tests, and document findings for improvement areas.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Spring-bus architecture review and gap remediation (U5)",
      "activity_description": "Review current spring-bus architecture and design specs, produce review notes, and implement necessary foundation-level refactors or fixes identified.",
      "most_likely_effort": 35
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Implement Ambari plugin upgrade RC to GA (U6)",
      "activity_description": "Extend Ambari plugin to support upgrading Spring XD 1.2 RC to 1.2 GA, including version detection and migration steps.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Document Spring XD upgrade procedure (U6)",
      "activity_description": "Write/upgrade documentation guiding users to perform the RC-to-GA upgrade via Ambari plugin.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Implement file:// URI support for LocalFileSystem (U7)",
      "activity_description": "Modify Hadoop filesystem abstraction in jdbchdfs job (and related modules) to accept fsUri=file:// and use LocalFileSystem, with appropriate warnings for multi-container scenarios.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-12",
      "activity_name": "Test file:// support (U7)",
      "activity_description": "Add unit/integration tests for local file system usage in single-node and verify behavior notes for distributed containers.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-13",
      "activity_name": "Implement Sqoop system property pass-through (U8)",
      "activity_description": "Add configuration option to specify system properties, and modify Sqoop job launcher to pass them as -D arguments to the spawned Java process.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-14",
      "activity_name": "Test Sqoop property feature (U8)",
      "activity_description": "Verify system properties are correctly propagated to Sqoop process via integration test.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-15",
      "activity_name": "Final integration testing, CI, and release documentation",
      "activity_description": "Run full test suite, integrate all changes, set up CI jobs, and finalize overall increment documentation and release notes.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 310
  }
}

